// inventory · кейсы inv-01, inv-02, inv-03, inv-04 (.qa/tests/inventory/) — только чтение, данные не меняются.
// עובד מחסן — через «כניסה כעובד» из admin-сессии (как auth-security/impersonation.spec.ts); admin.json не перезаписывается.
// Диалоги קליטה открываются и закрываются «ביטול» без сохранения.
import { test, expect, Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import * as zlib from 'zlib';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

const WORKER = 'עובד מחסן בדיקה';
const WITH_IMAGE = { name: 'אל די אדום קצר', category: 'סגריות' }; // товар с фото (на 2026-10-03)

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}

const qtyButtons = (page: Page) => page.getByRole('button', { name: /^קליטת מלאי — / });
const rowOfQty = (btn: ReturnType<Page['getByRole']>) =>
  btn.locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function checkIntakeFromQty(page: Page) {
  const first = qtyButtons(page).first();
  await expect(first).toBeVisible({ timeout: 20_000 });
  const name = (await first.getAttribute('aria-label'))!.replace(/^קליטת מלאי — /, '');
  await first.click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  await expect(dlg).toContainText(`${name} — בחרו כמות, ומקום אם הוא ידוע`);
  await expect(dlg.getByRole('combobox', { name: 'מוצר' })).toHaveCount(0); // товар уже выбран
  await expect(dlg.getByRole('spinbutton', { name: 'כמות', exact: true })).toBeVisible();
  // «יח'» may be part of a product name: check only the quantity field label («כמות», without «(יח')»)
  await expect(dlg.getByRole('spinbutton', { name: /\(יח['׳]\)/ })).toHaveCount(0);
  await expect(dlg.getByText(/^כמות\s*\(יח['׳]\)/)).toHaveCount(0);
  await expect(dlg.getByRole('button', { name: 'הוספה' })).toBeDisabled();
  await dlg.getByRole('button', { name: 'ביטול' }).click();
  await expect(dlg).toHaveCount(0);

  await rowOfQty(first).getByRole('button', { name: 'פעולות' }).click();
  await expect(page.getByRole('menuitem').first()).toBeVisible();
  await expect(page.getByRole('menuitem', { name: /קליטת מלאי/ })).toHaveCount(0);
  await expect(page.getByRole('menuitem', { name: 'הצג במפה' })).toBeVisible();
  await page.keyboard.press('Escape');
}

// --- минимальный разбор xlsx (zip + inlineStr) без зависимостей ---
function unzipEntry(buf: Buffer, entry: string): string {
  const eocd = buf.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  const count = buf.readUInt16LE(eocd + 10);
  let p = buf.readUInt32LE(eocd + 16);
  for (let i = 0; i < count; i++) {
    const method = buf.readUInt16LE(p + 10);
    const csize = buf.readUInt32LE(p + 20);
    const nlen = buf.readUInt16LE(p + 28);
    const elen = buf.readUInt16LE(p + 30);
    const clen = buf.readUInt16LE(p + 32);
    const local = buf.readUInt32LE(p + 42);
    const name = buf.toString('utf8', p + 46, p + 46 + nlen);
    if (name === entry) {
      const start = local + 30 + buf.readUInt16LE(local + 26) + buf.readUInt16LE(local + 28);
      const data = buf.subarray(start, start + csize);
      return (method === 0 ? data : zlib.inflateRawSync(data)).toString('utf8');
    }
    p += 46 + nlen + elen + clen;
  }
  throw new Error(`${entry} not found in xlsx`);
}

function sheetRows(xml: string, shared: string[]): string[][] {
  const dec = (s: string) => s.replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  return [...xml.matchAll(/<row[^>]*>([\s\S]*?)<\/row>/g)].map((r) =>
    [...r[1].matchAll(/<c([^>]*)>([\s\S]*?)<\/c>/g)].map((c) =>
      /t="s"/.test(c[1]) ? shared[Number(dec(c[2]))] : dec(c[2]),
    ),
  );
}

test.describe('inventory — עובד מחסן בדף ניהול מלאי', () => {
  test('עובד מחסן רואה תמונת מוצר וקטגוריה #6a8da5bc @desktop @prod-safe', async ({ page }) => {
    await impersonate(page, WORKER);
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'ניהול מלאי' })).toBeVisible({ timeout: 20_000 });
    for (const col of ['תמונה', 'קטגוריה', 'מק"ט', 'מיקום במחסן', 'במלאי', 'רף מינימום', 'סטטוס']) {
      await expect(page.getByRole('main').getByText(col, { exact: true }).first()).toBeVisible();
    }
    await expect(page.getByRole('img', { name: /^אין תמונה למוצר — / }).first()).toBeVisible();

    await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(WITH_IMAGE.name);
    const img = page.getByRole('img', { name: WITH_IMAGE.name, exact: true });
    await expect(img).toBeVisible({ timeout: 20_000 });
    await expect.poll(() => img.evaluate((i: HTMLImageElement) => i.naturalWidth)).toBeGreaterThan(0);
    const row = rowOfQty(page.getByRole('button', { name: `קליטת מלאי — ${WITH_IMAGE.name}`, exact: true }));
    await expect(row).toContainText(WITH_IMAGE.category);

    await backToAdmin(page);
  });

  test('עובד מחסן: לחיצה על הכמות — קליטה עם מוצר נבחר, שדה «כמות»; אין קליטה ב-⋮ #6a858f15 #6a8466f2 @desktop @prod-safe', async ({ page }) => {
    await impersonate(page, WORKER);
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'ניהול מלאי' })).toBeVisible({ timeout: 20_000 });
    await checkIntakeFromQty(page);
    await backToAdmin(page);
  });
});

test.describe('inventory — מפיץ (קריאה בלבד)', () => {
  test('רף מינימום מספר בלבד; סטטוס לפי כמות ורף #6a846775 #6a70b149 #6a84687f @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
    await expect(qtyButtons(page).first()).toBeVisible({ timeout: 20_000 });
    const mins = page.getByRole('button', { name: /^עדכון רף מינימום — / });
    for (const t of await mins.allInnerTexts()) expect(t.trim()).toMatch(/^\d+$/);
    for (const t of await qtyButtons(page).allInnerTexts()) expect(t.trim()).toMatch(/^\d+$/);

    const n = await qtyButtons(page).count();
    let checked = 0;
    for (let i = 0; i < n; i++) {
      const btn = qtyButtons(page).nth(i);
      const name = (await btn.getAttribute('aria-label'))!.replace(/^קליטת מלאי — /, '');
      const qty = Number((await btn.innerText()).trim());
      const min = Number((await page.getByRole('button', { name: `עדכון רף מינימום — ${name}`, exact: true }).innerText()).trim());
      const text = await rowOfQty(btn).innerText();
      const found = ['אזל', 'מלאי נמוך', 'במלאי'].filter((s) => text.includes(s));
      if (!found.length || text.includes('לא זמין')) continue; // недоступный товар — другой статус
      const expected = qty === 0 ? 'אזל' : qty <= min ? 'מלאי נמוך' : 'במלאי';
      expect(found, `${name}: ${qty}/${min}`).toEqual([expected]);
      checked++;
    }
    expect(checked).toBeGreaterThan(0);
  });

  test('קליטה מהכמות ומכפתור «קליטת מלאי» — שדות, בלי (יח\'), בלי קליטה ב-⋮ #6a858f15 #6a8466f2 #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
    await checkIntakeFromQty(page);

    await page.getByRole('button', { name: 'קליטת מלאי', exact: true }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    await expect(dlg).toContainText('בחרו מוצר וכמות; המקום אינו חובה');
    await expect(dlg.getByRole('combobox', { name: 'מוצר' })).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'זיהוי מוצר מתמונה' })).toBeVisible();
    const place = dlg.getByRole('combobox', { name: 'מקום היעד' });
    await expect(place).toBeVisible();
    await expect(place.locator('option').first()).toHaveText('ללא מקום — לשיוך בהמשך');
    expect(await place.locator('option').count()).toBeGreaterThan(1); // существующие ячейки карты
    await expect(dlg.getByText('לאיזה מקום (לא חובה)')).toBeVisible();
    await expect(dlg.getByRole('spinbutton', { name: 'כמות', exact: true })).toBeVisible();
    await expect(dlg.getByText('לא חובה — נשמרת ביומן התנועות')).toBeVisible();
    await expect(dlg).not.toContainText("יח'");
    await expect(dlg.getByRole('button', { name: 'הוספה' })).toBeDisabled();
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('ייצוא לאקסל — כל המוצרים עם מלאי ומחירים #6a749638 @desktop @prod-safe', async ({ page }, testInfo) => {
    await page.goto('/catalog');
    const allTab = page.getByRole('button', { name: /^הכל \d+$/ });
    await expect(allTab).toBeVisible({ timeout: 20_000 });
    const total = Number((await allTab.innerText()).match(/\d+/)![0]);

    await page.getByRole('button', { name: 'אקסל' }).click();
    const [download] = await Promise.all([
      page.waitForEvent('download'),
      page.getByRole('menuitem', { name: 'ייצוא לאקסל' }).click(),
    ]);
    expect(download.suggestedFilename()).toMatch(/^קטלוג-מוצרים-\d{4}-\d{2}-\d{2}\.xlsx$/);
    const file = testInfo.outputPath('export.xlsx');
    await download.saveAs(file);
    const buf = fs.readFileSync(file);
    let shared: string[] = [];
    try {
      shared = [...unzipEntry(buf, 'xl/sharedStrings.xml').matchAll(/<si>([\s\S]*?)<\/si>/g)].map((m) => m[1].replace(/<[^>]+>/g, ''));
    } catch { /* inlineStr — общих строк нет */ }
    const rows = sheetRows(unzipEntry(buf, 'xl/worksheets/sheet1.xml'), shared);
    const header = rows[0];
    for (const col of ['שם מוצר', 'קטגוריה', 'כמות באריזה', 'מחיר קנייה', 'מחיר מכירה', 'כמות במלאי']) {
      expect(header, `колонка «${col}»`).toContain(col);
    }
    expect(rows.length - 1).toBe(total);
  });
});
